        - if Union[i in 0,1,..] Parameters<g[i]> extends Union[i in 0,1,..] Parameters<f[i]> then
            - OK
        -  else
            - signature error
    - For each f[i]
        - hadMatch = false
        - gReturn = never;
        - For each g[j] // j'th intersection member
            - For each g[j][k] // k'th overload member of g[j]
